/* ── Bundled fonts ─────────────────────────────────────────── */
@font-face { font-family: 'Inter'; src: url('fonts/Inter-400.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: 'Inter'; src: url('fonts/Inter-500.woff2') format('woff2'); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: 'Inter'; src: url('fonts/Inter-600.woff2') format('woff2'); font-weight: 600; font-style: normal; font-display: swap; }

@font-face { font-family: 'Fraunces'; src: url('fonts/Fraunces-400.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: 'Fraunces'; src: url('fonts/Fraunces-400-italic.woff2') format('woff2'); font-weight: 400; font-style: italic; font-display: swap; }
@font-face { font-family: 'Fraunces'; src: url('fonts/Fraunces-500.woff2') format('woff2'); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: 'Fraunces'; src: url('fonts/Fraunces-500-italic.woff2') format('woff2'); font-weight: 500; font-style: italic; font-display: swap; }

@font-face { font-family: 'JetBrains Mono'; src: url('fonts/JetBrainsMono-400.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: 'JetBrains Mono'; src: url('fonts/JetBrainsMono-500.woff2') format('woff2'); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: 'JetBrains Mono'; src: url('fonts/JetBrainsMono-600.woff2') format('woff2'); font-weight: 600; font-style: normal; font-display: swap; }

/* CaskaydiaMono Nerd Font — LOAD-BEARING. ui/terminal.js uses this as the
   xterm fontFamily; xterm's canvas atlas bakes glyphs at open() time so the
   font MUST be synchronously available (hence the inlined base64). Do not
   remove without first migrating terminal.js to a different monospace-with-
   Nerd-glyphs font. */
@font-face { font-family: 'CaskaydiaMono Nerd Font'; src: url(data:font/ttf;base64,) format('truetype'); font-weight: 400; font-style: normal; font-display: block; }
@font-face { font-family: 'CaskaydiaMono Nerd Font'; src: url(data:font/ttf;base64,(--motion-pulse)) format('truetype'); font-weight: 700; font-style: normal; font-display: block; }
